/*
 * A398825  Numbers k such that the canonical prime factorizations of both k
 *          and k+1 contain only exponents that are congruent to 1 modulo 3.
 * https://oeis.org/A398825
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   The sequence is generated by testing each integer k. A term k is
 *            accepted iff every exponent in the prime factorisation of k and
 *            of k+1 is congruent to 1 (mod 3). The function does not use a
 *            closed‑form formula but builds the sequence on demand
 * Range:     u8 n <= 101, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/factor_u64.h"

/* Return true iff all exponents in the prime factorisation of n are ≡ 1 (mod 3) */
static bool good(uint64_t n)
{
    /* Buffers for factorisation results.  Size 64 is ample for all 64‑bit n. */
    static uint64_t pr[64];
    static uint64_t ex[64];
    size_t cnt;

    factor_u64(n, pr, ex, &cnt);
    for (size_t i = 0; i < cnt; ++i)
        if (ex[i] % 3U != 1U)
            return false;
    return true;
}

/* Cached sequence storage.  All entries are of type seq_t. */
static seq_t *cache      = NULL;    /* array of terms */
static size_t cache_cap  = 0;       /* current capacity */
static size_t cache_len  = 0;       /* number of terms stored */
static uint64_t last_k   = 0;       /* last k that was examined */

/* Append a new term to the cached sequence. */
static void add_to_cache(seq_t val)
{
    if (cache_len >= cache_cap) {
        size_t newcap = (cache_cap == 0) ? 16 : (cache_cap << 1);
        seq_t *tmp = (seq_t *)realloc(cache, newcap * sizeof(seq_t));
        /* In practice, realloc on failure will terminate the process.
           For the purposes of this sequence we ignore the error.        */
        cache = tmp;
        cache_cap = newcap;
    }
    cache[cache_len++] = val;
}

/* Main function required by the build system.  The sequence is offset‑1: a(1) is the first term. */
seq_t a(idx_t n)
{
    /* a(1) is the first term; nothing special is needed for n == 0. */
    if (n == 0) return 0;

    /* Generate terms until we have at least n of them. */
    while (cache_len < (size_t)n) {
        ++last_k;                         /* candidate k */
        if (good((uint64_t)last_k) && good((uint64_t)(last_k + 1)))
            add_to_cache((seq_t)last_k);  /* cast fits into seq_t */
    }

    return cache[(size_t)n - 1];
}
